1	package org.springframework.samples.petclinic.model;
2	
3	import java.time.LocalDate;
4	import java.time.temporal.ChronoUnit;
5	
6	/**
7	 * Derives an owner's numeric membership level.
8	 *
9	 * <p>Starts at {@code 1}; adds {@code 1} when an email address is present; adds {@code 1} when the
10	 * owner has no namesakes ({@code namesakeCount} is {@code 0}); these pre-tenure factors are capped
11	 * at {@code 3}. Level {@code 4} requires tenure of more than {@code 365} days — the number of days
12	 * between the owner's {@code registrationDate} and today — so a brand-new owner (zero tenure) never
13	 * exceeds level {@code 3}.
14	 */
15	public final class MembershipLevel {
16	
17	    /** Tenure, in days, that must be exceeded to reach level {@code 4}. */
18	    private static final long TENURE_DAYS_FOR_LEVEL_4 = 365;
19	
20	    private MembershipLevel() {
21	    }
22	
23	    /** Compute the membership level (1..4) for the given owner. */
24	    public static int of(Owner owner) {
25	        int level = 1;
26	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
27	            level++;
28	        }
29	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
30	            level++;
31	        }
32	        level = Math.min(level, 3);
33	        if (tenureDays(owner) > TENURE_DAYS_FOR_LEVEL_4) {
34	            level++;
35	        }
36	        return level;
37	    }
38	
39	    /** Days between the owner's {@code registrationDate} and today; {@code 0} when unknown. */
40	    private static long tenureDays(Owner owner) {
41	        LocalDate registrationDate = owner.getRegistrationDate();
42	        if (registrationDate == null) {
43	            return 0;
44	        }
45	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
46	    }
47	}
