1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.MembershipLevel;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class, imports = MembershipLevel.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName",
23	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "initials",
25	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "telephoneDisplay",
27	            expression = "java(TelephoneDisplay.of(owner.getTelephone()))")
28	    @Mapping(target = "membershipNumber",
29	            expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
30	    @Mapping(target = "checkDigit",
31	            expression = "java(CheckDigit.of(owner.getCustomerCode()))")
32	    @Mapping(target = "membershipLevel",
33	            expression = "java(MembershipLevel.of(owner))")
34	    @Mapping(target = "locality",
35	            expression = "java(Locality.of(owner.getCustomerCode()))")
36	    @Mapping(target = "contactPreference",
37	            expression = "java(ContactPreference.of(owner.getEmail()))")
38	    @Mapping(target = "ageBand",
39	            expression = "java(AgeBand.of(owner))")
40	    OwnerDto toOwnerDto(Owner owner);
41	
42	    Owner toOwner(OwnerDto ownerDto);
43	
44	    @Mapping(target = "id", ignore = true)
45	    @Mapping(target = "pets", ignore = true)
46	    Owner toOwner(OwnerFieldsDto ownerDto);
47	
48	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
49	
50	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
51	
52	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
53	        OwnerPageDto ownerPageDto = new OwnerPageDto();
54	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
55	        ownerPageDto.setPage(ownerPage.getNumber());
56	        ownerPageDto.setSize(ownerPage.getSize());
57	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
58	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
59	        return ownerPageDto;
60	    }
61	}
