1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.slf4j.Logger;
5	import org.slf4j.LoggerFactory;
6	import org.springframework.samples.petclinic.model.MembershipLevel;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Emits an audit line on successful create via the dedicated {@code AUDIT} logger, carrying the
11	 * new owner's id, its {@code customerCode}, its {@code registrationDate} and its
12	 * {@code membershipLevel}.
13	 *
14	 * <p>Runs after {@link SaveOwner}, so the owner has been assigned its generated id, and before
15	 * {@link RespondWithOwnerCreated}, so the line is only written once the create has succeeded.
16	 */
17	public class AuditOwnerCreated {
18	
19	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
20	
21	    public void service(@Val Owner owner) {
22	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
23	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
24	                MembershipLevel.of(owner));
25	    }
26	}
