9	/**
10	 * Assigns the owner's deterministic {@code householdId}: the first 12 hex characters of SHA-256 over
11	 * the normalized lastName, a {@code '|'} separator and the postcode. The household is therefore
12	 * keyed on {@code (lastName, postcode)} alone — owners with the same lastName (compared
13	 * case-insensitively with collapsed whitespace) and the same postcode receive the same id
14	 * automatically, regardless of creation order and without inspecting or updating any other owner.
15	 *
16	 * <p>The {@code sharesHousehold} request flag no longer creates the link — the id is always computed
17	 * here — it only bypasses the household duplicate block in {@link CheckOwnerIdentityUnique}.
18	 * Everything that keys off the household ({@link CheckOwnerIdentityUnique} duplicate detection and
19	 * the {@link AssignHouseholdSize} household size) reads this computed id.
20	 *
21	 * <p>Runs after {@link BuildOwner} (the entity exists) and before those steps.
22	 */
23	public class AssignHousehold {
24	
25	    public void service(@Val Owner owner) {
26	        String lastName = normalize(owner.getLastName());
27	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
28	        owner.setHouseholdId(deriveHouseholdId(lastName, postcode));
29	    }
